-- Aera cumulative DB updates after v30.57.
-- Run this ONE file on an existing `aera` database.
-- It includes v30.58, v30.62, v30.63, v30.65, v30.72 and v30.76 enhancement compatibility.
-- All included vendor patches are deterministic/idempotent according to their patch notes.

USE `aera`;

-- v30.58: game socket default is 5589.
UPDATE `servers` SET `Port`=5589 WHERE `id`=1 OR `Name`='Aera';


-- ===== v30_62_buffs_auras_combat.sql =====

-- Aera v30.62 - Buffs / Auras / Combat correction
-- MySQL 5.7 compatible. Safe to run again: the core mappings/effects below are rebuilt deterministically.

START TRANSACTION;

-- These three abilities are true self buffs. They must not route through player/monster damage.
UPDATE `skills` SET `Damage`=0.00, `Target`='s' WHERE `Name`='Prepared Strike';
UPDATE `skills` SET `Damage`=0.00, `Target`='s' WHERE `Name`='On Guard';
UPDATE `skills` SET `Damage`=0.00, `Target`='s' WHERE `Name`='Fortune';

-- Core aura rows use auras_effects as the authoritative modifier source.
UPDATE `auras`
SET `DamageIncrease`=0.00, `DamageTakenDecrease`=0.00
WHERE `Name` IN ('Armor Shred','Precise Blow','Aggression','Resolute','On Guard','Fortune');

-- Prepared Strike was described by the skill but was never mapped to an aura in the shipped DB.
SELECT 'Prepared Strike',30,'none',1.00,0.00,0.00
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `auras` WHERE `Name`='Prepared Strike');

UPDATE `auras`
SET `Duration`=30, `Category`='none', `Chance`=1.00, `DamageIncrease`=0.00, `DamageTakenDecrease`=0.00
WHERE `Name`='Prepared Strike';

-- Rebuild the authoritative effects for the baseline class auras.
DELETE ae
FROM `auras_effects` ae
INNER JOIN `auras` a ON a.`id`=ae.`AuraID`
WHERE a.`Name` IN ('Armor Shred','Aggression','Resolute','On Guard','Fortune','Prepared Strike');

-- Armor Shred: target takes 10% more incoming damage.
SELECT `id`,'cai',10.00,'+' FROM `auras` WHERE `Name`='Armor Shred' ORDER BY `id` LIMIT 1;

-- Aggression: +10% hit chance and +10% outgoing physical damage.
SELECT `id`,'thi',10.00,'+' FROM `auras` WHERE `Name`='Aggression' ORDER BY `id` LIMIT 1;
SELECT `id`,'cpo',10.00,'+' FROM `auras` WHERE `Name`='Aggression' ORDER BY `id` LIMIT 1;

-- Resolute: 10% all-damage resistance.
SELECT `id`,'cai',10.00,'-' FROM `auras` WHERE `Name`='Resolute' ORDER BY `id` LIMIT 1;

-- On Guard: 50% all-damage resistance for five seconds.
SELECT `id`,'cai',50.00,'-' FROM `auras` WHERE `Name`='On Guard' ORDER BY `id` LIMIT 1;

-- Fortune: +30% hit chance for ten seconds.
SELECT `id`,'thi',30.00,'+' FROM `auras` WHERE `Name`='Fortune' ORDER BY `id` LIMIT 1;

-- Rebuild the baseline skill -> aura links, including Prepared Strike.
DELETE sa
FROM `skills_auras` sa
INNER JOIN `skills` s ON s.`id`=sa.`SkillID`
WHERE s.`Name` IN ('Decisive Strike','Imbalancing Strike','Prepared Strike','Aggression','Resolute','On Guard','Fortune');

SELECT s.`id`,a.`id` FROM `skills` s CROSS JOIN `auras` a WHERE s.`Name`='Decisive Strike' AND a.`Name`='Armor Shred' ORDER BY s.`id`,a.`id` LIMIT 1;
SELECT s.`id`,a.`id` FROM `skills` s CROSS JOIN `auras` a WHERE s.`Name`='Imbalancing Strike' AND a.`Name`='Precise Blow' ORDER BY s.`id`,a.`id` LIMIT 1;
SELECT s.`id`,a.`id` FROM `skills` s CROSS JOIN `auras` a WHERE s.`Name`='Prepared Strike' AND a.`Name`='Prepared Strike' ORDER BY s.`id`,a.`id` LIMIT 1;
SELECT s.`id`,a.`id` FROM `skills` s CROSS JOIN `auras` a WHERE s.`Name`='Aggression' AND a.`Name`='Aggression' ORDER BY s.`id`,a.`id` LIMIT 1;
SELECT s.`id`,a.`id` FROM `skills` s CROSS JOIN `auras` a WHERE s.`Name`='Resolute' AND a.`Name`='Resolute' ORDER BY s.`id`,a.`id` LIMIT 1;
SELECT s.`id`,a.`id` FROM `skills` s CROSS JOIN `auras` a WHERE s.`Name`='On Guard' AND a.`Name`='On Guard' ORDER BY s.`id`,a.`id` LIMIT 1;
SELECT s.`id`,a.`id` FROM `skills` s CROSS JOIN `auras` a WHERE s.`Name`='Fortune' AND a.`Name`='Fortune' ORDER BY s.`id`,a.`id` LIMIT 1;

COMMIT;


-- ===== v30_63_buff_skills_aura_ack.sql =====

-- Aera v30.63 - self/friendly buff routing + aura acknowledgement hardening
-- MySQL 5.7 compatible. Safe to re-run.

START TRANSACTION;

-- These baseline abilities are buffs, never attacks.
UPDATE `skills` SET `Damage`=0.00, `Target`='s' WHERE `Name` IN ('Prepared Strike','On Guard','Fortune');

-- Prepared Strike needs a real aura row in older Aera databases.
SELECT 'Prepared Strike',30,'none',1.00,0.00,0.00
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `auras` WHERE `Name`='Prepared Strike');
UPDATE `auras` SET `Duration`=30,`Category`='none',`Chance`=1.00 WHERE `Name`='Prepared Strike';

-- Guarantee the core skill->aura mappings without creating duplicates.
SELECT s.`id`,a.`id` FROM `skills` s JOIN `auras` a ON a.`Name`='Prepared Strike'
WHERE s.`Name`='Prepared Strike'
  AND NOT EXISTS (SELECT 1 FROM `skills_auras` x WHERE x.`SkillID`=s.`id` AND x.`AuraID`=a.`id`)
LIMIT 1;
SELECT s.`id`,a.`id` FROM `skills` s JOIN `auras` a ON a.`Name`='On Guard'
WHERE s.`Name`='On Guard'
  AND NOT EXISTS (SELECT 1 FROM `skills_auras` x WHERE x.`SkillID`=s.`id` AND x.`AuraID`=a.`id`)
LIMIT 1;
SELECT s.`id`,a.`id` FROM `skills` s JOIN `auras` a ON a.`Name`='Fortune'
WHERE s.`Name`='Fortune'
  AND NOT EXISTS (SELECT 1 FROM `skills_auras` x WHERE x.`SkillID`=s.`id` AND x.`AuraID`=a.`id`)
LIMIT 1;

-- Reassert the intended baseline effects. This is deliberately deterministic so
-- an older broken Aera row cannot leave the skill visually active but inert.
DELETE ae FROM `auras_effects` ae JOIN `auras` a ON a.`id`=ae.`AuraID`
WHERE a.`Name` IN ('On Guard','Fortune');
SELECT `id`,'cai',50.00,'-' FROM `auras` WHERE `Name`='On Guard' ORDER BY `id` LIMIT 1;
SELECT `id`,'thi',30.00,'+' FROM `auras` WHERE `Name`='Fortune' ORDER BY `id` LIMIT 1;

COMMIT;


-- ===== v30_65_stat_points.sql =====

-- Aera v30.65 - persistent stat point allocation system
-- 3 points are earned for every level above level 1.
-- Existing players are backfilled from their current level.

CREATE TABLE IF NOT EXISTS `users_stats` (
  `UserID` int(11) UNSIGNED NOT NULL,
  `Points` int(11) UNSIGNED NOT NULL DEFAULT 0,
  `Strength` int(11) UNSIGNED NOT NULL DEFAULT 0,
  `Intellect` int(11) UNSIGNED NOT NULL DEFAULT 0,
  `Dexterity` int(11) UNSIGNED NOT NULL DEFAULT 0,
  `Endurance` int(11) UNSIGNED NOT NULL DEFAULT 0,
  `Wisdom` int(11) UNSIGNED NOT NULL DEFAULT 0,
  `Luck` int(11) UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`UserID`),
  CONSTRAINT `FK_users_stats_users` FOREIGN KEY (`UserID`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;

SELECT `id`, GREATEST((CAST(`Level` AS SIGNED) - 1) * 3, 0), 0, 0, 0, 0, 0, 0
FROM `users`
ON DUPLICATE KEY UPDATE `UserID`=VALUES(`UserID`);


-- ===== v30_72_assets_skills_auras_database.sql =====

-- Aera v30.72 - Assets_20260731 skill/aura database catalog
-- MySQL 5.7 compatible; safe to re-run.
-- Source SWF SHA256: 54ab0ac2693fbdd0afa0491e122bdbc96d942c2e29bbce81d2f54d5e5243f8a0
--
-- IMPORTANT: the SWF contains visual/linkage assets, not authoritative gameplay
-- numbers (damage, mana, cooldown, aura stat/value/duration). This patch therefore
-- imports every exported linkage and creates inert, unassigned skill/aura templates.
-- It does NOT invent mechanical aura effects.

START TRANSACTION;

SET @aera_has_col := (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='skills' AND COLUMN_NAME='AssetLinkage');
SET @aera_sql := IF(@aera_has_col=0, 'ALTER TABLE `skills` ADD COLUMN `AssetLinkage` varchar(255) NULL', 'SELECT 1');
PREPARE aera_stmt FROM @aera_sql;
EXECUTE aera_stmt;
DEALLOCATE PREPARE aera_stmt;

SET @aera_has_col := (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='skills' AND COLUMN_NAME='AssetGroup');
SET @aera_sql := IF(@aera_has_col=0, 'ALTER TABLE `skills` ADD COLUMN `AssetGroup` varchar(64) NULL', 'SELECT 1');
PREPARE aera_stmt FROM @aera_sql;
EXECUTE aera_stmt;
DEALLOCATE PREPARE aera_stmt;

SET @aera_has_col := (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='skills' AND COLUMN_NAME='AssetTemplate');
SET @aera_sql := IF(@aera_has_col=0, 'ALTER TABLE `skills` ADD COLUMN `AssetTemplate` tinyint(1) NOT NULL DEFAULT 0', 'SELECT 1');
PREPARE aera_stmt FROM @aera_sql;
EXECUTE aera_stmt;
DEALLOCATE PREPARE aera_stmt;

SET @aera_has_col := (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='auras' AND COLUMN_NAME='AssetLinkage');
SET @aera_sql := IF(@aera_has_col=0, 'ALTER TABLE `auras` ADD COLUMN `AssetLinkage` varchar(255) NULL', 'SELECT 1');
PREPARE aera_stmt FROM @aera_sql;
EXECUTE aera_stmt;
DEALLOCATE PREPARE aera_stmt;

SET @aera_has_col := (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='auras' AND COLUMN_NAME='AssetTemplate');
SET @aera_sql := IF(@aera_has_col=0, 'ALTER TABLE `auras` ADD COLUMN `AssetTemplate` tinyint(1) NOT NULL DEFAULT 0', 'SELECT 1');
PREPARE aera_stmt FROM @aera_sql;
EXECUTE aera_stmt;
DEALLOCATE PREPARE aera_stmt;

SET @aera_has_col := (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='auras_effects' AND COLUMN_NAME='AssetLinkage');
SET @aera_sql := IF(@aera_has_col=0, 'ALTER TABLE `auras_effects` ADD COLUMN `AssetLinkage` varchar(255) NULL', 'SELECT 1');
PREPARE aera_stmt FROM @aera_sql;
EXECUTE aera_stmt;
DEALLOCATE PREPARE aera_stmt;

SET @aera_has_col := (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='auras_effects' AND COLUMN_NAME='AssetTemplate');
SET @aera_sql := IF(@aera_has_col=0, 'ALTER TABLE `auras_effects` ADD COLUMN `AssetTemplate` tinyint(1) NOT NULL DEFAULT 0', 'SELECT 1');
PREPARE aera_stmt FROM @aera_sql;
EXECUTE aera_stmt;
DEALLOCATE PREPARE aera_stmt;

CREATE TABLE IF NOT EXISTS `aera_asset_symbols` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `CharacterID` int(11) UNSIGNED NOT NULL,
  `Linkage` varchar(255) NOT NULL,
  `Kind` varchar(24) NOT NULL,
  `AssetGroup` varchar(64) NOT NULL DEFAULT '',
  `SlotRef` varchar(8) NOT NULL DEFAULT '',
  `SourceSWF` varchar(128) NOT NULL,
  `SourceSHA256` char(64) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_aera_asset_symbols_linkage` (`Linkage`),
  KEY `idx_aera_asset_symbols_kind` (`Kind`),
  KEY `idx_aera_asset_symbols_group` (`AssetGroup`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

CREATE TABLE IF NOT EXISTS `auras_effects_assets` (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `Linkage` varchar(255) NOT NULL,
  `AssetGroup` varchar(64) NOT NULL DEFAULT '',
  `SlotRef` varchar(8) NOT NULL DEFAULT '',
  `SourceSWF` varchar(128) NOT NULL,
  `SourceSHA256` char(64) NOT NULL,
  `AuraID` int(11) UNSIGNED NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_auras_effects_assets_linkage` (`Linkage`),
  KEY `idx_auras_effects_assets_aura` (`AuraID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- Every exported SymbolClass linkage from the supplied SWF.

-- Visual effect linkages. These are catalogued separately because the SWF does not encode
-- AuraID / Stat / Value / Type mechanics needed by `auras_effects`.

-- Asset-backed skill templates. They are intentionally UNASSIGNED (no skills_assign rows)
-- and mechanically inert until you configure them in Admin/DB.

-- Aura visual templates from exported linkages. No fake stat effects are inserted.

-- Reassert the existing Aera/Warlord aura mechanics so this import never downgrades them.
UPDATE `skills` SET `Damage`=0.00,`Target`='s' WHERE `Name` IN ('Prepared Strike','On Guard','Fortune');
UPDATE `auras` SET `Duration`=30,`Category`='none',`Chance`=1.00 WHERE `Name`='Prepared Strike';
UPDATE `auras` SET `Duration`=5,`Category`='none',`Chance`=1.00 WHERE `Name`='On Guard';
UPDATE `auras` SET `Duration`=10,`Category`='none',`Chance`=1.00 WHERE `Name`='Fortune';

COMMIT;


